// Legacy FinancialReportService.cs (.NET Framework style)
public class FinancialReportService
{
    private readonly string _connectionString;

    public FinancialReportService(string connectionString)
    {
        _connectionString = connectionString;
    }

    public ReportResult ProcessTransactions(List<TransactionDto> transactions, DateTime cutoff)
    {
        var result = new ReportResult();
        decimal runningTotal = 0;

        foreach (var tx in transactions)
        {
            if (tx.Date < cutoff)
            {
                if (tx.Type == 1) // Credit
                {
                    runningTotal += tx.Amount;
                }
                else if (tx.Type == 2) // Debit
                {
                    runningTotal -= tx.Amount;
                }
                else if (tx.Type == 3) // Transfer
                {
                    runningTotal -= (tx.Amount + tx.Fee);
                }
            }
        }

        result.FinalBalance = runningTotal;
        result.ProcessedOn = DateTime.UtcNow;
        return result;
    }
}

