// Modernized .NET 9 Implementation
namespace Enterprise.Finance.Reporting;

public enum TransactionType : byte
{
    Credit = 1,
    Debit = 2,
    Transfer = 3
}

public readonly record struct TransactionDto(
    Guid Id,
    DateTime Date,
    TransactionType Type,
    decimal Amount,
    decimal Fee = 0m);

public readonly record struct ReportResult(
    decimal FinalBalance,
    DateTime ProcessedOn);

public sealed class FinancialReportService(TimeProvider timeProvider)
{
    public ReportResult ProcessTransactions(ReadOnlySpan<TransactionDto> transactions, DateTime cutoff)
    {
        decimal runningTotal = 0m;

        foreach (ref readonly var tx in transactions)
        {
            if (tx.Date >= cutoff) continue;

            runningTotal += tx.Type switch
            {
                TransactionType.Credit => tx.Amount,
                TransactionType.Debit => -tx.Amount,
                TransactionType.Transfer => -(tx.Amount + tx.Fee),
                _ => throw new InvalidOperationException($"Unsupported transaction type: {tx.Type}")
            };
        }

        return new ReportResult(runningTotal, timeProvider.GetUtcNow().UtcDateTime);
    }
}

