[MemoryDiagnoser]
public class RefactoringBenchmark
{
    private List<TransactionDto> _legacyList = null!;
    private TransactionDto[] _modernArray = null!;
    private readonly FinancialReportService _modernService = new(TimeProvider.System);
    private readonly DateTime _cutoff = new(2026, 3, 1);

    [GlobalSetup]
    public void Setup()
    {
        var sample = Enumerable.Range(0, 10_000)
            .Select(i => new TransactionDto(
                Guid.NewGuid(), 
                DateTime.UtcNow.AddDays(-i % 30), 
                (TransactionType)(i % 3 + 1), 
                100m + i, 
                2m))
            .ToArray();

        _legacyList = [.. sample];
        _modernArray = sample;
    }

    [Benchmark]
    public ReportResult ModernSpanCalculation()
    {
        return _modernService.ProcessTransactions(_modernArray.AsSpan(), _cutoff);
    }
}
